/**
 * Shared constants and plain data types for dsh-history-rewind.
 */

/** HTTP route prefix served by the Host half for the browser channel. */
export const ROUTE_PREFIX = '/dsh-history-rewind/api'

/** Root directory (under $DSH_HOME) holding every shadow-store artifact. */
export const HISTORY_ROOT_DIRNAME = '.dsh-history-rewind'

/** Directory holding per-session bare repos (`repos/session-<id>.git`). */
export const REPOS_DIRNAME = 'repos'

/** Directory holding per-project workspace bare repos (`repos-ws/<project>.git`). */
export const REPOS_WS_DIRNAME = 'repos-ws'

/** Directory holding pre-rewind backups (session files + workspace trees). */
export const BACKUPS_DIRNAME = 'backups'

/** Directory holding per-project exclusive locks. */
export const LOCKS_DIRNAME = 'locks'

/** Branch name carrying the never-jumped original road of every session repo. */
export const MAIN_BRANCH = 'main'

/** Prefix of road branches (post-jump forks produced by content changes). */
export const ROAD_REF_PREFIX = 'refs/heads/road-'

/** Legacy old-model fork ref prefix (kept for purge compatibility only). */
export const LEGACY_ABANDONED_PREFIX = 'refs/heads/abandoned-'

/** Tree path prefix of the session artifact inside session-repo commits. */
export const SESSION_TREE_DIR = 'session-'

/** Basename of the official session artifact file inside tree + official layout. */
export const SESSION_FILE_BASENAME = 'session.jsonl.zstd'

/** Basename of the global config file, stored right under the history root. */
export const CONFIG_FILENAME = 'config.json'

/**
 * Seed content for a workspace's `.gitignore` when a fresh workspace has none
 * yet. This is ONLY a starting point written once per workspace — after that
 * the workspace's own `.gitignore` is the sole source of truth for what a
 * snapshot excludes; nothing here is merged into the walk at snapshot time.
 */
export const DEFAULT_GITIGNORE_TEMPLATE: readonly string[] = [
  '.git',
]

/** Fixed identity stamped on shadow commits (never the user's git identity). */
export const COMMIT_AUTHOR_NAME = 'dsh-history'
/** Fixed author email for shadow commits. */
export const COMMIT_AUTHOR_EMAIL = 'history@dsh.local'

/** Age after which an abandoned lockfile is considered stale and stealable. */
export const LOCK_STALE_MS = 60_000

/** Commit-message marker prefix (the contract prose begins right after it). */
export const MESSAGE_PREFIX = 'dsh-history:'

/** git log format used by the timeline data source. */
export const LOG_FORMAT = '%H|%P|%s|%ct'

/** Settings namespace owned by this plugin (lowercase kebab-case per the seam). */
export const SETTINGS_NAMESPACE = 'history-rewind'

/** Durable config value shape (mirrors the Host schema). */
export interface HistoryRewindConfig {
  /** Whether session history rewind is enabled. */
  enabled: boolean
  /**
   * Global default `.gitignore` template (newline-joined text, one pattern
   * per line). Written into a workspace's `.gitignore` only the FIRST time
   * that workspace is snapshotted and no `.gitignore` exists there yet. A
   * workspace that already has a `.gitignore` — whether pre-existing or
   * edited by hand afterwards — is never touched or merged with this value.
   */
  gitignoreTemplate: string
  /**
   * Soft budget for the shadow store, in GB. Advisory ONLY: reaching it never
   * deletes anything and never blocks a snapshot — the UI just escalates its
   * warning. Automatic eviction is deliberately out of scope, because the only
   * thing there is to evict is rewind history the user may still need.
   */
  cacheCapacityGb: number
}

/** Schema defaults. */
export const HISTORY_REWIND_DEFAULTS: HistoryRewindConfig = {
  enabled: true,
  gitignoreTemplate: `${DEFAULT_GITIGNORE_TEMPLATE.join('\n')}\n`,
  cacheCapacityGb: 100,
}

/** Usage ratio at which the capacity bar turns amber (healthy below this). */
export const CACHE_WARN_RATIO = 0.75
/** Usage ratio at which the capacity bar turns red. */
export const CACHE_FULL_RATIO = 0.9

/** What a cache-clear request targets. */
export type CacheScope = 'session' | 'workspace' | 'both'
